const mark=(p,fill,extra='')=>`<path d="${p.d}" transform="translate(${p.x} ${p.y})" fill="${fill}" fill-rule="evenodd"${extra?' '+extra:''}/>`;

// Slim can in the house rendering. l is the left edge of the body, t the y of the lid centre; the
// base always sits on the common ground line. `fields` are the label's colour blocks, `art` the
// marks and lettering; the highlight bar and speckle are drawn between the two so that they do not
// leave ghost marks on dark artwork, and the body shading goes over everything.
function slimCan(slug,title,{l,t,base,fields,art,defs='',gloss=.17,speckle=16}) {
  const r=200-l,w=r-l,rx=w/2-3;
  const body=`M${l+3} ${t}Q100 ${t-7} ${r-3} ${t}L${r} ${t+7}V223Q${r} 233 100 233T${l} 223V${t+7}Z`;
  return wrap(slug,title,`${shadow(r2(w/2+12))}<path d="${body}" fill="${base}"/>
<g clip-path="${ref('bodyclip')}">${fields}
<path d="M${l+6.5} ${t+13}V217" fill="none" stroke="#fff" stroke-opacity="${gloss}" stroke-width="2.4"/>
${Array.from({length:speckle},(_,i)=>`<ellipse cx="${l+8+i*19%(w-15)}" cy="${t+14+i*37%(219-t-14)}" rx="${i%4?.5:.9}" ry="${i%4?.8:1.4}" fill="#fff" opacity=".2"/>`).join('')}
${art}<path d="${body}" fill="${ref('shade')}" opacity=".8"/></g>
<ellipse cx="100" cy="${t}" rx="${rx}" ry="6" fill="${ref('metal')}" stroke="#9ca7a4" stroke-width="1.1"/>
<ellipse cx="100" cy="${t}" rx="${r2(rx-3.5)}" ry="4" fill="none" stroke="#8d9892" stroke-width=".7"/>
<ellipse cx="103.4" cy="${r2(t+.8)}" rx="6" ry="2.4" fill="#657169"/>
<path d="M95 ${r2(t-1.7)}h7.6q4.2 0 3.4 2.5t-5.9 2.5h-4.2q-4.2-.8-.9-5" fill="none" stroke="#e6e8de" stroke-width="1.9"/>
<path d="M${l+3} 227q${r2(w/2-3)} 10 ${w-6} 0" fill="none" stroke="${ref('metal')}" stroke-width="3.6"/>
<path d="M${l+5.5} 230.4q${r2(w/2-5.5)} 6 ${w-11} 0" fill="none" stroke="#fff" stroke-opacity=".5" stroke-width="1"/>`,
`<clipPath id="__ID__bodyclip"><path d="${body}"/></clipPath>${defs}`);
}

// USDA Organic seal, radius s, centred on x,y. `ring` is the label colour printed round it.
const usda=(x,y,s,ring)=>`<g transform="translate(${x} ${y})"><circle r="${s}" fill="#fff" stroke="${ring}" stroke-width="${r2(s*.09)}"/>
<path d="M${r2(-s*.92)} ${r2(s*.05)}A${r2(s*.92)} ${r2(s*.92)} 0 0 0 ${r2(s*.92)} ${r2(s*.05)}Z" fill="#1c8a4d"/>
<path d="M${r2(-s*.7)} ${r2(s*.62)}Q0 ${r2(s*.36)} ${r2(s*.72)} ${r2(s*.5)}M${r2(-s*.5)} ${r2(s*.8)}Q${r2(s*.1)} ${r2(s*.5)} ${r2(s*.72)} ${r2(s*.5)}M${r2(-s*.2)} ${r2(s*.92)}Q${r2(s*.3)} ${r2(s*.62)} ${r2(s*.72)} ${r2(s*.5)}" fill="none" stroke="#fff" stroke-width="${r2(s*.07)}"/>
${text(0,r2(-s*.14),'USDA',r2(s*.66),'#1c8a4d',`font-weight="bold" textLength="${r2(s*1.26)}" lengthAdjust="spacingAndGlyphs"`)}
${text(0,r2(s*.43),'ORGANIC',r2(s*.4),'#fff',`font-weight="bold" textLength="${r2(s*1.5)}" lengthAdjust="spacingAndGlyphs" stroke="#14683a" stroke-width="${r2(s*.035)}" paint-order="stroke"`)}</g>`;

// ---------------------------------------------------------------- 7 fl oz RISE Brewing Co. nitro can
// A 2 in by 5.5 in can (retailer dimension diagram): 66 units wide against 90 for a 12 oz can.
// Label positions measured on the manufacturer render of the Original Black can:
// icon y = 58.6 + 0.0725 * photo y.
const SUN=[100,97.1];
const rays=Array.from({length:108},(_,i)=>{const a=(i+.5)*Math.PI/54,c=Math.cos(a),s=Math.sin(a);return `M${r2(SUN[0]+8*c)} ${r2(SUN[1]+8*s)}L${r2(SUN[0]+80*c)} ${r2(SUN[1]+80*s)}`;}).join('');
function riseCan(slug,title,p) {
  const l=67,t=59,bandTop=123.7,bandBot=134.9;
  const fields=`<path d="M${l} ${t-9}h66v${r2(bandTop-t+9)}h-66Z" fill="${p.field}"/>
<path d="${rays}" fill="none" stroke="${p.ray}" stroke-width=".62"/>
<circle cx="${SUN[0]}" cy="${SUN[1]}" r="11.5" fill="${ref('sun')}"/>
<path d="M${l} ${bandTop}h66v${r2(bandBot-bandTop)}h-66Z" fill="${p.band}"/>
<path d="M${l} ${bandBot}h66v${r2(226.2-bandBot)}h-66Z" fill="${ref('lower')}"/>
<path d="M${l} 226.2h66v8h-66Z" fill="${ref('metal')}"/>`;
  const art=`${mark(P.rise,'none',`stroke="${p.outline}" stroke-width="1.5" stroke-linejoin="round"`)}${mark(P.rise,p.red)}
${mark(P.brewing,p.ink)}
${mark(p.flavorMark,'#fff')}
${mark(P.nitro,p.text)}${mark(P.coldBrew,p.text)}${mark(P.coffee,p.text)}
${p.icon}
${mark(P.dairyFree,p.small)}
${usda(100,201.8,7.4,p.ring)}
${mark(P.flOz,p.small)}${mark(P.serveCold,p.serve)}`;
  return slimCan(slug,title,{l,t,base:p.field,fields,art,gloss:p.gloss,speckle:p.speckle,defs:`
<radialGradient id="__ID__sun" gradientUnits="userSpaceOnUse" cx="${SUN[0]}" cy="${SUN[1]}" r="11.5"><stop offset=".78" stop-color="${p.core}"/><stop offset="1" stop-color="${p.ray}"/></radialGradient>
<linearGradient id="__ID__lower" gradientUnits="userSpaceOnUse" x1="${l}" y1="0" x2="${200-l}" y2="0"><stop stop-color="${p.lower[0]}"/><stop offset=".3" stop-color="${p.lower[1]}"/><stop offset=".62" stop-color="${p.lower[2]}"/><stop offset="1" stop-color="${p.lower[3]}"/></linearGradient>`});
}
