const sprig=`${mark(P.sprig,'#f6f3f1','stroke="#9a5d4e" stroke-width=".5" stroke-linejoin="round"')}`;
const RISE_BLACK={field:'#f7f1e8',ray:'#ecb640',core:'#eaaa24',outline:'#f0b22e',red:'#d8262a',ink:'#251f17',band:'#d92526',lower:['#34302d','#433e3a','#282421','#2b2724'],text:'#f1efee',small:'#e7ac30',serve:'#f1efee',ring:'#4f2f27',flavorMark:P.originalBlack,icon:beans,gloss:.13,speckle:0};
